          this._onsetE = 0;
          this._onsetHit = -1;
          this.rxBase = 0;
          this.acq = false;
          this.base = 0;
          this.symIdx = 0;
          this.des = new Array(23).fill(0);
          this.gr = 1;
          this.gi = 0;
          this.g2 = 1;
          this.outbits = [];
          this._rxHold = [];
          this.rxPts = [];
          this.rxFrameIdx = 0;
          this.rxCoder.reset();
          this.uState = "hunt";
          this.uArmed = false;
          this.uMarks = 0;
          this.uBit = 0;
          this.uByte = 0;
